fn frame(t: i32) {
    host::display::clear(0x000000);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    let s: i32 = 70;
    let ca: i32 = host::math::cos(t);
    let sa: i32 = host::math::sin(t);
    let cb: i32 = host::math::cos(t / 2);
    let sb: i32 = host::math::sin(t / 2);
    let mut vx = [0, 0, 0, 0, 0, 0, 0, 0];
    let mut vy = [0, 0, 0, 0, 0, 0, 0, 0];
    let mut i: i32 = 0;
    while i < 8 {
        let x0: i32 = ((i & 1) * 2 - 1) * s;
        let y0: i32 = (((i >> 1) & 1) * 2 - 1) * s;
        let z0: i32 = (((i >> 2) & 1) * 2 - 1) * s;
        let x1: i32 = (x0 * ca - z0 * sa) / 256;
        let z1: i32 = (x0 * sa + z0 * ca) / 256;
        let y2: i32 = (y0 * cb - z1 * sb) / 256;
        let z2: i32 = (y0 * sb + z1 * cb) / 256;
        let depth: i32 = z2 + 340;
        vx[i] = cx + (x1 * 360) / depth;
        vy[i] = cy + (y2 * 360) / depth;
        i = i + 1;
    }
    let ea = [0, 1, 3, 2, 4, 5, 7, 6, 0, 1, 2, 3];
    let eb = [1, 3, 2, 0, 5, 7, 6, 4, 4, 5, 6, 7];
    let mut k: i32 = 0;
    while k < 12 {
        let a: i32 = ea[k];
        let b: i32 = eb[k];
        host::display::draw_line(vx[a], vy[a], vx[b], vy[b], 0x66ffcc);
        k = k + 1;
    }
    host::display::present();
}
